pub fn acp_applies(
    receiver_condition: AccessControlReceiverCondition,
    target_condition: &AccessControlTargetCondition,
    ident_memberof: Option<&Vec<crate::Uuid>>,
    ident_uuid: crate::Uuid,
    entry: &Entry,
