    entry: &Entry,
) -> bool {
    let mut i = 0;
    while i < related_acp.len() {
        let acd = &related_acp[i];
        if acp_applies(acd.receiver_condition, &acd.target_condition, ident_memberof, ident_uuid, entry) {
            return true;
