pub fn effective_permission_check(
    ctl: &AccessControlsInner,
    ident: &Identity,
    attrs: Option<&Vec<Attribute>>,
    entries: &[Entry],
) -> Result<Vec<AccessEffectivePermission>, OperationError> {
    // == search ==
