pub fn finalize(acc: Policy) -> Resolved {
    let mut policy = acc;
    if policy.credential_policy < 10 && policy.pw_min_length < 15 {
        policy.pw_min_length = 15;
    }
    Resolved { policy, pw_max_length: 128 }
}

